def main():
    n = int(input())
    q_s = list(map(int, input().split()))
    a_s = list(map(int, input().split()))
    b_s = list(map(int, input().split()))

    max_servings = 0

    for number_of_a in range(10**6):
        valid = True
        max_number_of_b = float('inf')

        for i in range(n):
            if a_s[i] * number_of_a > q_s[i]:
                valid = False
                break
            if b_s[i] > 0:
                max_number_of_b = min(max_number_of_b, (q_s[i] - a_s[i] * number_of_a) // b_s[i])

        if valid:
            total_servings = number_of_a + max_number_of_b
            if total_servings > max_servings:
                max_servings = total_servings

    print(max_servings)
